-- Reference text. {z:...}, {n:...}, {s:id:...}, {a:...} and {f:...} are
-- filled in with the game's own names (see ns.LocText in Core/Locale.lua).
L["Loyalty"] = "Lealtà"
L["Your pet's loyalty rises through six ranks: Rebellious, Unruly, Submissive, Dependable, Faithful, and Best Friend."] = "La lealtà del tuo famiglio sale attraverso sei gradi: Ribelle, Indisciplinato, Sottomesso, Affidabile, Fedele e Migliore amico."
L["Rebellious - Very low loyalty. Failing to feed the pet, dismissing it frequently, or getting yourself or the pet killed repeatedly has a high probability of the pet abandoning you."] = "Ribelle - Lealtà molto bassa. Non nutrirlo, congedarlo spesso o morire ripetutamente (tu o lui) rende molto probabile che ti abbandoni."
L["Unruly - Your pet is still not convinced, so you'll need to keep treating it well and not abusing its trust. It can still leave you at this stage."] = "Indisciplinato - Il tuo famiglio non è ancora convinto: continua a trattarlo bene senza abusare della sua fiducia. Può ancora lasciarti in questa fase."
L["Submissive - The pet is more willing to put up with some bad luck occasionally, and needs less food to keep it happy."] = "Sottomesso - Il famiglio sopporta meglio un po' di sfortuna ogni tanto e ha bisogno di meno cibo per restare contento."
L["Dependable - Loyalty is still improving and food requirements are continuing to go down."] = "Affidabile - La lealtà continua a crescere e il fabbisogno di cibo continua a calare."
L["Faithful - Less food is required, and the likelihood of running off is very slim."] = "Fedele - Serve meno cibo e la probabilità che scappi è minima."
L["Best Friend - The highest loyalty rank. The pet requires the least amount of food to keep happy and goes longer between feedings."] = "Migliore amico - Il grado di lealtà più alto. Il famiglio ha bisogno di pochissimo cibo per essere felice e resiste più a lungo tra un pasto e l'altro."
L["Higher loyalty also increases the training points your pet has available (see Training Points below)."] = "Una lealtà più alta aumenta anche i punti addestramento disponibili del famiglio (vedi Punti addestramento qui sotto)."
L["Pet Food & Happiness"] = "Cibo e felicità"
L["Your pet's happiness affects its damage output: Happy pets deal 125% damage, Content pets deal 100%, and Unhappy pets deal only 75%."] = "La felicità del famiglio influisce sui suoi danni: i famigli felici infliggono il 125% dei danni, quelli soddisfatti il 100% e quelli scontenti solo il 75%."
L["There are six food categories: Bread, Cheese, Fish, Fruit, Fungus, and Meat. Each pet family will only eat certain categories - see that family's entry in the Pet Index for its diet. Boars are the only family that will eat anything from all six categories."] = "Esistono sei categorie di cibo: pane, formaggio, pesce, frutta, funghi e carne. Ogni famiglia mangia solo alcune categorie - vedi la sua voce nell'Indice famigli per la sua dieta. I cinghiali sono l'unica famiglia che mangia tutte e sei le categorie."
L["Lower-loyalty pets need to be fed more often to stay happy; higher-loyalty pets go longer between feedings."] = "I famigli meno leali vanno nutriti più spesso per restare felici; quelli più leali resistono più a lungo tra un pasto e l'altro."
L["Training Points"] = "Punti addestramento"
L["Training points are earned as your pet gains levels and loyalty, following the formula: pet level x (loyalty rank - 1)."] = "I punti addestramento si ottengono man mano che il famiglio sale di livello e di lealtà, secondo la formula: livello del famiglio x (grado di lealtà - 1)."
L["A level 60 pet at the highest loyalty rank (Best Friend) has a maximum of 300 training points."] = "Un famiglio di livello 60 al grado di lealtà più alto (Migliore amico) ha al massimo 300 punti addestramento."
L["Training points are spent to teach your pet abilities, whether learned from a trainer or from taming. A pet can only have 4 active abilities learned at any one time, so choose which ones to train carefully."] = "I punti addestramento servono a insegnare abilità al famiglio, apprese da un addestratore o addomesticando. Un famiglio può avere solo 4 abilità attive alla volta, quindi scegli con cura."
L["Taming a Pet"] = "Addomesticare un famiglio"
L["Hunters can start taming pets at level 10."] = "I cacciatori possono iniziare ad addomesticare famigli dal livello 10."
L["You can only tame a beast that is at or below your own level."] = "Puoi addomesticare solo una bestia di livello pari o inferiore al tuo."
L["Taming channels the Tame Beast spell; while channeling it you lose 100% of your armor, leaving you vulnerable to attack."] = "Addomesticare canalizza {s:1515:Tame Beast}; durante la canalizzazione perdi il 100% della tua armatura e sei vulnerabile."
L["Abilities such as Concussive Shot, Aspect of the Monkey, and Freezing Trap can help protect you while taming. For tougher beasts, having a Mage or Druid keep it crowd-controlled (Polymorph or Hibernate) helps too."] = "Abilità come {s:5116:Concussive Shot}, {s:13163:Aspect of the Monkey} e {s:1499:Freezing Trap} ti proteggono mentre addomestichi. Per le bestie più dure aiuta anche un mago o un druido che la tenga sotto controllo ({s:118:Polymorph} o {s:2637:Hibernate})."
L["Learning & Teaching Abilities"] = "Imparare e insegnare abilità"
L["Some pet abilities can't be learned from a trainer at all - they can only be learned by taming a pet that already knows them."] = "Alcune abilità dei famigli non si possono imparare da un addestratore - solo addomesticando un famiglio che le conosce già."
L["Taming that 'teacher' pet doesn't grant you the ability right away. The pet must actively use that ability in combat - it won't count just by knowing it or using it outside of combat - and you must keep fighting with that pet until you get a message that you've learned the skill."] = "Addomesticare quel famiglio 'insegnante' non ti dà subito l'abilità. Il famiglio deve usarla attivamente in combattimento - conoscerla o usarla fuori dal combattimento non conta - e devi continuare a combattere con lui finché non ricevi un messaggio che l'hai imparata."
L["Once the ability is learned, it's learned permanently - you can release the teacher pet and spend training points to teach the ability to any other compatible pet, including your main one."] = "Una volta imparata, l'abilità resta per sempre - puoi liberare il famiglio insegnante e spendere punti addestramento per insegnarla a qualsiasi altro famiglio compatibile, compreso il principale."
L["Stable Masters & Stable Slots"] = "Stallieri e posti nella stalla"
L["A Stable Master is an NPC found in most friendly hubs who lets you store extra pets you aren't currently using."] = "Uno stalliere è un PNG presente nella maggior parte dei luoghi amichevoli, che custodisce i famigli che non stai usando."
L["You can only have one active pet out at a time, but you can keep two more stabled with a Stable Master - three pets total."] = "Puoi avere un solo famiglio attivo alla volta, ma puoi tenerne altri due nella stalla - tre famigli in tutto."
L["Pet Command Modes"] = "Modalità di comando del famiglio"
L["Aggressive - the pet attacks any enemy that comes within its aggro radius on its own, without needing a direct command."] = "Aggressivo - il famiglio attacca da solo qualsiasi nemico entri nel suo raggio di aggressione, senza bisogno di un comando."
L["Assist - the pet attacks whatever target its master attacks, automatically switching targets if its master does. With no target to assist, it behaves like Defensive."] = "Assistenza - il famiglio attacca il bersaglio del padrone e cambia bersaglio automaticamente se lo fa il padrone. Senza bersaglio si comporta come Difensivo."
L["Defensive - the pet won't attack on its own, but will retaliate immediately if it or its master is actually hit."] = "Difensivo - il famiglio non attacca da solo, ma reagisce subito se lui o il padrone vengono colpiti."
L["Passive - the pet will not attack unless given a direct Attack command, and ignores attacks made against itself or its master."] = "Passivo - il famiglio attacca solo con un comando di attacco diretto e ignora gli attacchi contro di sé o il padrone."
L["Compact Critter Carrier - a Hunter-only crafted item, made by Blacksmiths. Using it places a Compact Critter Carrier that lasts 3 minutes, letting Hunters in your group access their stabled pets from anywhere, without needing to find a Stable Master."] = "{s:1266920:Compact Critter Carrier} - un oggetto solo per cacciatori, creato dai fabbri. Piazza per 3 minuti un trasportatore che permette ai cacciatori del gruppo di accedere ai famigli nella stalla da qualsiasi luogo, senza cercare uno stalliere."
L["Casting the Compact Critter Carrier has a 45 second cast time and a 30 minute cooldown, and requires level 40 to use."] = "Il lancio dura 45 secondi, ha un tempo di recupero di 30 minuti e richiede il livello 40."
L["A level 70 pet at the highest loyalty rank (Best Friend) has a maximum of 350 training points."] = "Un famiglio di livello 70 al grado di lealtà più alto (Migliore amico) ha al massimo 350 punti addestramento."
L["New in The Burning Crusade"] = "Novità di The Burning Crusade"
L["There are six new pet families: Dragonhawk, Nether Ray, Ravager, Serpent, Sporebat and Warp Stalker."] = "Ci sono sei nuove famiglie di famigli: {f:Dragonhawk}, {f:Nether Ray}, {f:Ravager}, {f:Serpent}, {f:Sporebat} e {f:Warp Stalker}."
L["There are six new pet abilities: Avoidance and Cobra Reflexes from the pet trainer, and Fire Breath, Gore, Poison Spit and Warp from taming."] = "Ci sono sei nuove abilità: {a:Avoidance} e {a:Cobra Reflexes} dall'addestratore di famigli, e {a:Fire Breath}, {a:Gore}, {a:Poison Spit} e {a:Warp} addomesticando."
L["Every pet now attacks at the same speed (2.0), so attack speed no longer matters when choosing a pet."] = "Tutti i famigli ora attaccano alla stessa velocità (2,0), quindi la velocità d'attacco non conta più nella scelta."
L["Pets now gain part of their hunter's stats: about 30% of your stamina, 35% of your armor, 40% of your resistances, and 22% of your ranged attack power as melee attack power."] = "I famigli ora ricevono parte delle statistiche del cacciatore: circa il 30% della tua tempra, il 35% della tua armatura, il 40% delle tue resistenze e il 22% della tua potenza d'attacco a distanza come potenza d'attacco in mischia."
L["A loyal, versatile pack hunter at home in nearly any fight."] = "Un cacciatore di branco leale e versatile, a suo agio in quasi ogni scontro."
L["A swift, agile predator that relies on speed and stealth."] = "Un predatore rapido e agile che punta su velocità e furtività."
L["A venomous ambusher that lies in wait for its prey."] = "Un predatore velenoso che attende in agguato la sua preda."
L["A thick-hided brawler that shrugs off punishment."] = "Un attaccabrighe dalla pelle spessa che incassa i colpi."
L["A tusked omnivore willing to eat almost anything."] = "Un onnivoro con le zanne disposto a mangiare quasi di tutto."
L["An ambush predator that lurks at the water's edge."] = "Un predatore in agguato che si apposta sulla riva."
L["A scavenging flier that picks apart weakened prey."] = "Un volatile spazzino che finisce le prede indebolite."
L["A heavily armored crustacean built like a walking fortress."] = "Un crostaceo pesantemente corazzato, costruito come una fortezza ambulante."
L["A powerful, territorial brawler known for its ground-shaking slam."] = "Un attaccabrighe potente e territoriale, noto per il colpo che fa tremare il suolo."
L["A fast, vicious hunter that tears into prey with claw and fang."] = "Un cacciatore rapido e feroce che squarcia le prede con artigli e zanne."
L["A flightless ground bird with a surprisingly sturdy frame."] = "Un uccello corridore che non vola, dalla struttura sorprendentemente robusta."
L["An armored arachnid whose sting wears down its prey."] = "Un aracnide corazzato il cui pungiglione sfianca la preda."
L["A heavily-shelled reptile built to absorb punishment."] = "Un rettile dal guscio spesso fatto per incassare."
L["A nimble night flier that screeches and dives at its prey."] = "Un agile volatile notturno che strilla e si tuffa sulla preda."
L["A scrappy, fast-moving pack hunter."] = "Un cacciatore di branco rapido e combattivo."
L["A silent, sharp-eyed hunter that swoops on prey from above."] = "Un cacciatore silenzioso dalla vista acuta che piomba sulla preda dall'alto."
L["An elemental serpent that breathes crackling lightning."] = "Un serpente elementale che sputa fulmini crepitanti."
L["A venomous ambusher that binds foes in webbing."] = "Un predatore velenoso che imprigiona i nemici nelle ragnatele."
L["A nimble flier that uses sound to disorient its prey."] = "Un volatile agile che disorienta la preda con il suono."
L["A scrappy pack hunter known for its infectious bite."] = "Un cacciatore di branco combattivo, noto per il morso infetto."
L["A sharp-eyed raptor-bird with a taste for shiny trinkets."] = "Un rapace dalla vista acuta con un debole per i ninnoli luccicanti."
L["A clever, quick companion unique to Forever, known for its trickery."] = "Un compagno furbo e svelto, esclusivo di Forever, noto per i suoi trucchi."
L["A fiery winged hunter that breathes flame over everything in front of it."] = "Un cacciatore alato e infuocato che sputa fiamme su tutto ciò che ha davanti."
L["A spiny Outland predator that gores and tears into its prey."] = "Un predatore spinoso delle Terre Esterne che incorna e squarcia la preda."
L["A blinking Outland stalker that warps straight to its target."] = "Un predatore delle Terre Esterne che si teletrasporta dritto sul bersaglio."
L["A drifting creature of the fungal forests of Zangarmarsh."] = "Una creatura fluttuante delle foreste di funghi di {z:Zangarmarsh}."
L["A gliding ray from the skies of Outland, hardy but lightly armored."] = "Una razza planante dei cieli delle Terre Esterne, robusta ma poco corazzata."
L["A coiled snake that spits poison at its prey."] = "Un serpente attorcigliato che sputa veleno sulla preda."
L["A white, pink-winged rare bat that spawns near Cold Hearth Manor, using a Sonic Burst that damages and silences nearby enemies."] = "Un pipistrello raro bianco dalle ali rosa che compare vicino a Cold Hearth Manor; il suo grido sonico ferisce e silenzia i nemici vicini."
L["An albino rare bat native to the deepest, lightless reaches of Razorfen Kraul, which may explain its unusual coloring and blindness."] = "Un pipistrello raro albino dei recessi più profondi e bui di Razorfen Kraul, il che spiegherebbe il colore insolito e la cecità."
L["A rare plagued bear roaming northwest of Durnholde Keep, formerly known as Little Samras before its corrupted Forsaken-influenced appearance."] = "Un orso raro appestato che si aggira a nord-ovest di Durnholde Keep, un tempo noto come Little Samras prima del suo aspetto corrotto dai Reietti."
L["A rare black bear found roaming northeastern Ashenvale, with a leaping charge attack and an armor-reducing swipe."] = "Un orso nero raro del nord-est di {z:Ashenvale}, con una carica in salto e una zampata che riduce l'armatura."
L["A rare black bear found prowling the Ruins of Isildien in southern Feralas."] = "Un orso nero raro che si aggira tra le Ruins of Isildien, nel sud di {z:Feralas}."
L["A rare brown bear that roams the area between Ambermill and Deep Elem Mine in Silverpine Forest."] = "Un orso bruno raro che vaga tra Ambermill e Deep Elem Mine, in {z:Silverpine Forest}."
L["A rare brown bear found in southern Felwood, capable of enraging, hibernating to heal, and a wide swiping attack."] = "Un orso bruno raro del sud di {z:Felwood}, capace di infuriarsi, andare in letargo per curarsi e colpire con un'ampia zampata."
L["The only white bear in Dun Morogh, found in the Tundrid Hills south of Amberstill Ranch."] = "L'unico orso bianco di {z:Dun Morogh}, nelle Tundrid Hills a sud di Amberstill Ranch."
L["A rare helboar in the Blasted Lands, historically prized as the highest-level tameable boar in the game."] = "Un cinghiale infernale raro di {z:Blasted Lands}, un tempo apprezzato come il cinghiale addomesticabile di livello più alto del gioco."
L["A rare vulture that roams several farmland sites across Westfall, including the Dead Acre and Furlbrow's Pumpkin Patch."] = "Un avvoltoio raro che sorvola diverse fattorie di {z:Westfall}, tra cui il Dead Acre e Furlbrow's Pumpkin Patch."
L["A rare condor found southwest of Farstrider Lodge in Loch Modan."] = "Un condor raro a sud-ovest di Farstrider Lodge, in {z:Loch Modan}."
L["A rare two-headed vulture wreathed in fire, found in Tanaris, using Crimson Fury and Fire Nova attacks."] = "Un avvoltoio raro a due teste avvolto dal fuoco, in {z:Tanaris}, che attacca con il fuoco."
L["A rare white buzzard, one of the rarest colorations in the Badlands, found circling the central part of the zone."] = "Una poiana bianca rara, una delle colorazioni più rare di {z:Badlands}, che volteggia sopra il centro della zona."
L["A rare two-headed vulture found in the Blasted Lands."] = "Un avvoltoio raro a due teste in {z:Blasted Lands}."
L["A rare nightsaber that stays stealthed in the Withering Thicket north of the Ruins of Auberdine."] = "Una sciabola notturna rara che resta furtiva nel Withering Thicket, a nord delle rovine di Auberdine."
L["A roaming rare lion found in Desolace."] = "Un leone raro errante in {z:Desolace}."
L["The most contested rare pet in the game: a cat with a 1.0 base attack speed, the fastest available, excellent for interrupting enemy casters in PvP. Spawns at one of three points in the Badlands."] = "Il famiglio raro più conteso del gioco: un felino con velocità d'attacco base 1,0, la più rapida disponibile, ottimo per interrompere gli incantatori nel PvP. Compare in uno di tre punti di {z:Badlands}."
L["A rare frostsaber found south of Lake Al'Ameth in Teldrassil, which uses Tendon Rip to slow its prey."] = "Una sciabola del gelo rara a sud del lago Al'Ameth, in {z:Teldrassil}, che rallenta la preda recidendo i tendini."
L["A rare cheetah resting beneath a tree north of the Crossroads in the Northern Barrens, alongside a pride of lions."] = "Un ghepardo raro che riposa sotto un albero a nord del Crocevia, nel nord di {z:The Barrens}, insieme a un branco di leoni."
L["A rare aqua-colored frostsaber found at Frostsaber Rock in Winterspring, famed in lore as the quarry of a rivalry between Hemet Nesingwary and Shado 'Fitz' Farstrider."] = "Una sciabola del gelo rara color acquamarina al Frostsaber Rock, in {z:Winterspring}, famosa nella storia come preda della rivalità tra Hemet Nesingwary e Shado 'Fitz' Farstrider."
L["A distinctive black lion resting in the shade of a large tree northwest of Ratchet."] = "Un leone nero inconfondibile che riposa all'ombra di un grande albero a nord-ovest di Ratchet."
L["A rare lion found in the Golden Plains east of Thunder Bluff, historically valued for its fast attack speed."] = "Un leone raro delle Golden Plains a est di {z:Thunder Bluff}, un tempo apprezzato per la sua rapida velocità d'attacco."
L["A rare crocolisk roaming Dustwallow Marsh, using an infected bite and a bleeding rip attack."] = "Un crocolisco raro che si aggira in {z:Dustwallow Marsh}, con un morso infetto e un attacco che fa sanguinare."
L["A large albino crocolisk that lazily swims the canals of Stormwind City, near Stormwind Keep's exterior."] = "Un grosso crocolisco albino che nuota pigramente nei canali di {z:Stormwind City}, vicino al castello."
L["A rare crocolisk found in the waters of the Loch in Loch Modan."] = "Un crocolisco raro nelle acque del lago di {z:Loch Modan}."
L["A rare gorilla found in Mistvale Valley in northern Stranglethorn Vale."] = "Un gorilla raro nella Mistvale Valley, nel nord di {z:Stranglethorn Vale}."
L["A uniquely colored rare gorilla found at Fungal Rock in Un'Goro Crater, the only tameable gorilla of its shade."] = "Un gorilla raro dal colore unico a Fungal Rock, in {z:Un'Goro Crater}, l'unico gorilla addomesticabile di quella tinta."
L["A rare hyena found in Desolace, whose Rabies attack saps enemy health regeneration and stats."] = "Una iena rara di {z:Desolace}, la cui rabbia riduce la rigenerazione della salute e le statistiche del nemico."
L["A rare brown hyena found in Tanaris, once a target for field-sampling hunters."] = "Una iena bruna rara di {z:Tanaris}, un tempo bersaglio dei cacciatori che raccoglievano campioni."
L["A rare purple hyena found roaming east of Vendetta Point in the Southern Barrens."] = "Una iena viola rara che si aggira a est di Vendetta Point, nel sud di {z:The Barrens}."
L["A rare hyena prowling the Blasted Lands."] = "Una iena rara che si aggira in {z:Blasted Lands}."
L["A spectral-looking rare owl that flies between Irontree Woods and Talonbranch Glade in Felwood; taming it briefly angers the Cenarion Circle but costs no reputation."] = "Un gufo raro dall'aspetto spettrale che vola tra Irontree Woods e Talonbranch Glade, in {z:Felwood}; addomesticarlo irrita per poco il Circolo Cenariano, ma non costa reputazione."
L["An elite rare raptor that roams the ridge southeast of the Sludge Fen in the Barrens, known for its Leaping Rush attack."] = "Un raptor raro élite che percorre la cresta a sud-est del Sludge Fen, in {z:The Barrens}, noto per il suo attacco in salto."
L["A rare raptor found in Dustwallow Marsh."] = "Un raptor raro di {z:Dustwallow Marsh}."
L["A rare yellow raptor that watches over her brood within the Raptor Ridge cavern in the Wetlands."] = "Una raptor gialla rara che veglia sulla sua covata nella caverna di Raptor Ridge, in {z:Wetlands}."
L["A rare scorpid found south of the Southfury Watershed, among the rocks near the Southfury River in Durotar."] = "Uno scorpide raro a sud della Southfury Watershed, tra le rocce vicino al fiume Southfury, in {z:Durotar}."
L["A rare scorpid found in Silithus, with a Fatal Sting that only triggers when it is badly wounded."] = "Uno scorpide raro di {z:Silithus}, il cui pungiglione fatale si attiva solo quando è gravemente ferito."
L["A rare scorpid roaming the heights above Highperch in Thousand Needles."] = "Uno scorpide raro che si aggira sulle alture sopra Highperch, in {z:Thousand Needles}."
L["A rare scorpid found in the Blasted Lands, striking with poison bolts and venom splash."] = "Uno scorpide raro di {z:Blasted Lands}, che colpisce con dardi velenosi e schizzi di veleno."
L["A rare tarantula that spawns in a cave in Loch Modan, combining a poisonous bite with an immobilizing web."] = "Una tarantola rara che compare in una grotta di {z:Loch Modan}, unendo un morso velenoso a una ragnatela immobilizzante."
L["A rare tarantula in Hillsbrad Foothills valued for its unusually high Creeper Ichor drop rate."] = "Una tarantola rara di {z:Hillsbrad Foothills}, apprezzata per la probabilità di bottino di icore di strisciante insolitamente alta."
L["A rare tarantula found in Silithus, armed with poison and web attacks."] = "Una tarantola rara di {z:Silithus}, armata di veleno e ragnatele."
L["A rare lava spider found in Searing Gorge, delivering a lingering Deadly Poison."] = "Un ragno di lava raro di {z:Searing Gorge}, che infligge un veleno mortale persistente."
L["A reddish-brown rare tarantula found near Alther's Mill in Redridge Mountains."] = "Una tarantola rara bruno-rossiccia vicino ad Alther's Mill, in {z:Redridge Mountains}."
L["A rare spider found in Venomweb Vale in Tirisfal Glades."] = "Un ragno raro nella Venomweb Vale, in {z:Tirisfal Glades}."
L["A rare spider that lurks in and around the cave known as the Skittering Dark in Silverpine Forest."] = "Un ragno raro che si annida dentro e attorno alla grotta Skittering Dark, in {z:Silverpine Forest}."
L["A rare spider found deep within Jasperlode Mine in Elwynn Forest, combining poison with webbing crowd control."] = "Un ragno raro nelle profondità della Jasperlode Mine, in {z:Elwynn Forest}, che unisce veleno e ragnatele."
L["A rare spider found at Thelgen Rock in the Wetlands."] = "Un ragno raro a Thelgen Rock, in {z:Wetlands}."
L["A rare spider found just outside Darkmist Cavern in Dustwallow Marsh."] = "Un ragno raro appena fuori dalla Darkmist Cavern, in {z:Dustwallow Marsh}."
L["A distinctively red-and-green rare venom spider found in a cave southeast of Darkshire in Duskwood."] = "Un ragno velenoso raro rosso e verde, in una grotta a sud-est di Darkshire, in {z:Duskwood}."
L["A flamingo-pink rare tallstrider found southwest of Thunder Bluff in Mulgore."] = "Uno zampalunga raro rosa fenicottero a sud-ovest di {z:Thunder Bluff}, in {z:Mulgore}."
L["A teal-skinned rare tallstrider roaming southern Darkshore, usually accompanied by two Foreststrider Fledglings."] = "Uno zampalunga raro dalla pelle verde-azzurra che si aggira nel sud di {z:Darkshore}, di solito accompagnato da due {n:Foreststrider Fledgling}."
L["A rare turtle found along the shore beneath the Overlook Cliffs in the Hinterlands."] = "Una tartaruga rara sulla riva sotto gli Overlook Cliffs, in {z:The Hinterlands}."
L["A rare turtle, formerly known as Optimistic Benj, found in the Alterac Mountains / Hillsbrad border area."] = "Una tartaruga rara, un tempo chiamata Optimistic Benj, al confine tra {z:Alterac Mountains} e {z:Hillsbrad Foothills}."
L["A rare wind serpent that patrols south of the Ruins of Taurajo in the Southern Barrens, armed with Fireball and Flame Spike."] = "Un serpente del vento raro che pattuglia a sud delle Ruins of Taurajo, nel sud di {z:The Barrens}, armato di palle di fuoco e spuntoni di fiamma."
L["A rare wind serpent found over the Quagmire in Dustwallow Marsh."] = "Un serpente del vento raro sopra il Quagmire, in {z:Dustwallow Marsh}."
L["A rare wind serpent that circles a path southwest of the Ruins of Ravenwind and west of Camp Ataya in Feralas."] = "Un serpente del vento raro che volteggia a sud-ovest delle Ruins of Ravenwind e a ovest di Camp Ataya, in {z:Feralas}."
L["A rare timber wolf found in northeastern Feralas."] = "Un lupo dei boschi raro nel nord-est di {z:Feralas}."
L["A rare timber wolf in northwestern Ashenvale, once famous for an unusually fast attack speed."] = "Un lupo dei boschi raro nel nord-ovest di {z:Ashenvale}, un tempo famoso per la velocità d'attacco insolitamente rapida."
L["A rare worg found near Dreadmaul Rock in the Burning Steppes, one of only a few wolves with a unique skin."] = "Un worg raro vicino a Dreadmaul Rock, in {z:Burning Steppes}, uno dei pochi lupi con un manto unico."
L["A dark grey rare timber wolf found around the haystacks at Featherbeard's Hovel in the Hinterlands."] = "Un lupo dei boschi raro grigio scuro attorno ai covoni di Featherbeard's Hovel, in {z:The Hinterlands}."
L["A grey-and-white rare worg, unusual among the typically black worgs of Silverpine Forest, roaming between the Forsaken High Command and Valgan's Field."] = "Un worg raro grigio e bianco, insolito tra i worg neri di {z:Silverpine Forest}, che si aggira tra il Forsaken High Command e Valgan's Field."
L["A rare wolf found in the Badlands that can enrage and snarl for bonus damage."] = "Un lupo raro di {z:Badlands} che può infuriarsi e ringhiare per infliggere danni extra."
L["A rare frost wolf found near the eastern side of Iceflow Lake in Dun Morogh."] = "Un lupo del gelo raro vicino alla sponda est dell'Iceflow Lake, in {z:Dun Morogh}."
L["A rare wolf that roams between Brightwood Grove and the Darkened Bank in Duskwood."] = "Un lupo raro che vaga tra Brightwood Grove e Darkened Bank, in {z:Duskwood}."
L["A rare worg found in Felwood, capable of a horrifying howl, infected wounds, and tendon-ripping bites."] = "Un worg raro di {z:Felwood}, capace di un ululato terrificante, ferite infette e morsi che recidono i tendini."
L["A rare bear that watches over her territory across a wide stretch of northern Elwynn Forest."] = "Un'orsa rara che veglia sul suo territorio in un'ampia fascia del nord di {z:Elwynn Forest}."
L["A rare bear drifting through the fog-wreathed terraces of Zephras Isle, who has picked up a Savage Rend bite more typical of the island's raptors than its own kind."] = "Un orso raro che vaga tra le terrazze avvolte nella nebbia di Zephras Isle e ha imparato un morso {a:Savage Rend}, più tipico dei raptor dell'isola che della sua specie."
L["A rare cat that roams widely across Durotar, from the coast up into the northern hills."] = "Un felino raro che percorre tutto {z:Durotar}, dalla costa fino alle colline del nord."
L["A pale rare cat that ranges widely across Dun Morogh's foothills, rarely seen twice in the same place."] = "Un felino raro e pallido che percorre le colline di {z:Dun Morogh}, raramente visto due volte nello stesso posto."
L["A rare fox skulking the floating terraces of Zephras Isle, rarely seen for long before it slips away again."] = "Una volpe rara che sgattaiola sulle terrazze fluttuanti di Zephras Isle, raramente visibile a lungo prima di sparire di nuovo."
L["A rare owl haunting the moonlit boughs of Teldrassil, whose piercing shriek carries long after it's gone quiet again."] = "Un gufo raro che infesta i rami illuminati dalla luna di {z:Teldrassil}, il cui strido acuto risuona a lungo dopo che tace."
L["A rare tallstrider striding the open plateaus of Zephras Isle, its fern-green plumage blending into the isle's hanging gardens."] = "Uno zampalunga raro che percorre gli altipiani di Zephras Isle, con un piumaggio verde felce che si confonde con i giardini pensili dell'isola."
L["A rare frost-pale wolf prowling Tirisfal Glades, whose rasping, broken howl gives it its name."] = "Un lupo raro pallido come la brina che si aggira in {z:Tirisfal Glades}; il suo ululato roco e spezzato gli dà il nome."
L["A rare crab that wanders the western coast of Desolace, north of Shadowprey Village."] = "Un granchio raro che vaga sulla costa ovest di {z:Desolace}, a nord di Shadowprey Village."
L["A rare crocolisk that roams the lakes and rivers of Nagrand, in three separate areas of the zone."] = "Un crocolisco raro che percorre laghi e fiumi di {z:Nagrand}, in tre aree separate della zona."
L["A unique bear denned in the tunnel near North Gate Outpost, reached by heading east from Ironforge past Steelgrill's Depot."] = "Un orso unico che vive nel tunnel vicino a North Gate Outpost; ci si arriva andando verso est da {z:Ironforge}, oltre Steelgrill's Depot."
L["A black bear that dens in a cave in the hills south of Thelsamar, though he wanders the path and valley around it too."] = "Un orso nero che vive in una grotta sulle colline a sud di Thelsamar, anche se vaga pure sul sentiero e nella valle intorno."
L["A scorpid that spawns on the hill just north and west of The Den, above the orc starting burrow."] = "Uno scorpide che compare sulla collina a nord-ovest della Tana, sopra la grotta iniziale degli orchi."
L["A panther that patrols the top of a hill near the Tkashi Ruins, southwest of Nesingwary's Expedition."] = "Una pantera che pattuglia la cima di una collina vicino alle Tkashi Ruins, a sud-ovest della spedizione di Nesingwary."
L["A panther found on a hill along the western coast, near the arena grounds north of Grom'Gol Base Camp."] = "Una pantera su una collina della costa ovest, vicino all'arena a nord del campo base di Grom'gol."
L["A wind serpent found south of Camp Taurajo, near the quilboar territory around Blackthorn Ridge."] = "Un serpente del vento a sud di Camp Taurajo, vicino al territorio dei verrospino attorno a Blackthorn Ridge."
L["A bear denned in a hidden mountain cave due east of Bashal'Aran, up a hidden path north from Auberdine."] = "Un orso in una grotta nascosta in montagna, esattamente a est di Bashal'Aran, lungo un sentiero nascosto a nord di Auberdine."
L["A spider found at the falls atop Wellspring River, on either side of Wellspring Lake - she doesn't patrol between the two."] = "Un ragno alle cascate in cima al Wellspring River, su entrambi i lati del Wellspring Lake - non si sposta tra i due."
L["Guards the Webwood Egg inside Shadowthread Cave, home to Teldrassil's webwood spiders."] = "Custodisce il Webwood Egg nella Shadowthread Cave, casa dei ragni di {z:Teldrassil}."
L["A common grey wolf that prowls the plains south and west of Camp Narache, around the lake and out toward Red Cloud Mesa - a single wide hunting ground, not a single camp."] = "Un comune lupo grigio che si aggira nelle pianure a sud e a ovest di Camp Narache, attorno al lago e fino a Red Cloud Mesa - un'unica ampia zona di caccia, non un campo fisso."
